import * as T from './vendor/three.module.js';
// Fine stones sit along the path shoulders; no collision objects block the walking line.
export function createTrailMargins(scene,paths,height){const poses=[],colors=[];let seed=819;const rnd=()=>{seed=(Math.imul(seed,1664525)+1013904223)>>>0;return seed/4294967296;},pose=new T.Object3D();for(const path of paths)for(let i=1;i<path.points.length;i++){const a=path.points[i-1],b=path.points[i],dx=b[0]-a[0],dz=b[1]-a[1],len=Math.hypot(dx,dz);if(len<.1)continue;for(let j=0;j<Math.ceil(len*2);j++){const t=rnd(),side=j%2?1:-1,off=(path.width/2+.08+rnd()*.28)*side,x=a[0]+dx*t+dz/len*off,z=a[1]+dz*t-dx/len*off,size=.025+rnd()*.065;pose.position.set(x,height(x,z)+size*.25,z);pose.rotation.set(rnd(),rnd()*6,rnd());pose.scale.set(size*1.5,size*.55,size);pose.updateMatrix();poses.push(pose.matrix.clone());colors.push(new T.Color().setHSL(.1,.08,.48+rnd()*.22));}}
 const rock=new T.InstancedMesh(new T.IcosahedronGeometry(1,1),new T.MeshStandardMaterial({color:'#ffffff',roughness:1}),poses.length);poses.forEach((m,i)=>{rock.setMatrixAt(i,m);rock.setColorAt(i,colors[i]);});rock.receiveShadow=true;rock.userData.kind='natural-trail-shoulder-gravel';rock.userData.count=poses.length;scene.add(rock);return rock;}
